function perfilEstatisticas(){
 const a=perfilTreinos.map(t=>({...t,km:Number(t.distancia_m)/1000,seg:Number(t.duracao_s),pts:Number(t.pontos)})).filter(t=>t.km>0&&t.seg>0);
 const soma=(f)=>a.reduce((v,t)=>v+f(t),0),km=soma(t=>t.km),seg=soma(t=>t.seg),pts=soma(t=>t.pts);
 const melhorKm=a.length?Math.max(...a.map(t=>t.km)):0;
 const melhorRitmo=a.length?Math.min(...a.map(t=>t.seg/t.km)):0;
 const velocidade=seg?km*3600/seg:0;
 const meses={};a.forEach(t=>{const m=String(t.iniciado_em).slice(0,7);meses[m]=(meses[m]||0)+t.km});
 const ultimos=Object.entries(meses).sort((x,y)=>x[0].localeCompare(y[0])).slice(-6);
 const maximo=Math.max(1,...ultimos.map(x=>x[1]));
 const medals=[
 {ico:'🥉',titulo:'Primeiros passos',desc:'Concluir o primeiro treino',ok:a.length>=1},
 {ico:'🥈',titulo:'Constância',desc:'Concluir 10 treinos',ok:a.length>=10},
 {ico:'🥇',titulo:'100 km acumulados',desc:'Alcançar 100 km de treinos',ok:km>=100},
 {ico:'🏅',titulo:'Meio do Mundo',desc:'Alcançar 500 km acumulados',ok:km>=500},
 {ico:'🏆',titulo:'Corredor de longa distância',desc:'Concluir um treino de 21,1 km',ok:melhorKm>=21.1}
 ];
 return `<div class="panel perfil-dashboard"><div class="treino-section-head"><div><span class="treino-eyebrow">MEU DESEMPENHO</span><h3>📊 Estatísticas do corredor</h3></div><div class="treino-actions"><button class="btn secondary" onclick="carregarPerfilTreinos()">↻ Atualizar dados</button><button class="btn dark" onclick="compartilharPerfilCorredor()">🖼️ Compartilhar imagem</button></div></div>${!onlineUser?'<p class="notice">Entre na sua conta para visualizar estatísticas e medalhas dos treinos registrados online.</p>':perfilTreinosErro?'<p class="notice">'+esc(perfilTreinosErro)+'</p>':''}<div class="perfil-stats"><div class="card"><small>Distância acumulada</small><strong>${km.toFixed(2).replace('.',',')} km</strong></div><div class="card"><small>Treinos válidos</small><strong>${a.length}</strong></div><div class="card"><small>Tempo total</small><strong>${treinoDuracao(seg)}</strong></div><div class="card"><small>Pontos acumulados</small><strong>${pts.toFixed(2).replace('.',',')}</strong></div><div class="card"><small>Velocidade média geral</small><strong>${velocidade.toFixed(2).replace('.',',')} km/h</strong></div><div class="card"><small>Ritmo médio geral</small><strong>${seg?treinoDuracao(Math.round(seg/km))+' /km':'—'}</strong></div></div><h4>🏆 Recordes pessoais de treino</h4><div class="perfil-stats"><div class="card"><small>Maior distância em um treino</small><strong>${melhorKm.toFixed(2).replace('.',',')} km</strong></div><div class="card"><small>Melhor ritmo médio de um treino</small><strong>${a.length?treinoDuracao(Math.round(melhorRitmo))+' /km':'—'}</strong></div></div><h4>📈 Evolução mensal da distância</h4><div class="perfil-chart">${ultimos.map(([mes,dist])=>`<div class="perfil-bar"><span>${dist.toFixed(1).replace('.',',')} km</span><div class="perfil-bar-track"><div style="height:${Math.max(3,dist/maximo*100)}%"></div></div><small>${esc(mes.slice(5)+'/'+mes.slice(0,4))}</small></div>`).join('')||'<p class="muted">Os gráficos aparecerão após o primeiro treino online válido.</p>'}</div><h4>🎖️ Medalhas digitais de treino</h4><div class="perfil-medals">${medals.map(m=>`<article class="card ${m.ok?'':'perfil-medal-locked'}"><div class="perfil-medal-icon">${m.ico}</div><strong>${esc(m.titulo)}</strong><small>${esc(m.desc)}</small><span>${m.ok?'Conquistada':'Bloqueada'}</span></article>`).join('')}</div><p class="muted">Medalhas virtuais automáticas baseadas em treinos GPS válidos registrados online. Não equivalem a premiação oficial nem a resultados homologados de provas. Treinos removidos pela administração não são contabilizados.</p><h4>📋 Últimos treinos</h4><div class="tablewrap"><table><thead><tr><th>Data</th><th>Distância</th><th>Tempo</th><th>Ritmo</th><th>Pontos</th></tr></thead><tbody>${a.slice(0,15).map(t=>`<tr><td>${esc(new Date(t.iniciado_em).toLocaleDateString('pt-BR'))}</td><td>${t.km.toFixed(2).replace('.',',')} km</td><td>${treinoDuracao(t.seg)}</td><td>${treinoDuracao(Math.round(t.seg/t.km))} /km</td><td>${t.pts.toFixed(2).replace('.',',')}</td></tr>`).join('')||'<tr><td colspan="5">Nenhum treino online válido encontrado.</td></tr>'}</tbody></table></div></div>`;
}
function perfil(){return `${onlinePanel()}${perfilEstatisticas()}${fotoPerfil()}${passaporte()}${medalhasParticipacao()}${heading('Meu perfil e resultados','Pré-cadastro da temporada 2027 • sincronização automática após entrar na conta')}<div class="two"><div class="panel"><h3>🏃 Pré-cadastro para 2027</h3><p class="muted">Preencha seu perfil. Com a conta online conectada, os dados são salvos automaticamente no banco ao concluir o formulário. Se você preencher antes de entrar, o sistema tentará sincronizar após o login.</p><form id="profileForm"><div class="formgrid"><div class="full"><label>Nome de exibição</label><input name="nome" required maxlength="90" value="${esc(profile?.nome||'')}"></div><div><label>Município</label><select name="cidade">${['Macapá','Santana','Oiapoque','Porto Grande','Laranjal do Jari','Tartarugalzinho','Pedra Branca do Amapari','Mazagão','Calçoene','Amapá','Ferreira Gomes','Itaubal','Cutias','Pracuúba','Serra do Navio','Vitória do Jari'].map(v=>`<option ${profile?.cidade===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Categoria</label><select name="sexo">${['Masculino','Feminino','PcD'].map(v=>`<option ${profile?.sexo===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Modalidade do corredor</label><select name="nivel"><option value="Amador" ${(!profile?.nivel||profile.nivel==='Amador')?'selected':''}>Corredor amador</option><option value="Elite" ${profile?.nivel==='Elite'?'selected':''}>Corredor de elite</option></select></div><div><label>Faixa etária</label><select name="faixa">${['Até 17','18–29','30–39','40–49','50–59','60–69','70+'].map(v=>`<option ${profile?.faixa===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label>Classe esportiva PcD (se aplicável)</label><input name="classe" value="${esc(profile?.classe||'')}" placeholder="Definir após homologação"></div></div><button class="btn dark">${profile?'Atualizar pré-cadastro':'Concluir pré-cadastro 2027'}</button></form></div><div class="panel"><h3>⏱️ Resultados oficiais • 2027</h3><p class="muted">${!profile?'Primeiro, conclua o pré-cadastro.':!seasonIsOpen()?'Envio disponível a partir de 1º de janeiro de 2027.':'Envie apenas resultados de provas realizadas em 2027.'}</p><form id="resultForm"><fieldset ${!seasonIsOpen()?'disabled':''} style="border:0;padding:0;margin:0"><div class="formgrid"><div class="full"><label>Nome oficial da corrida (será exibido na medalha digital)</label><input name="prova" required minlength="3" maxlength="120" placeholder="Ex.: 3ª Corrida do IFAP"></div><div><label>Data da prova</label><input type="date" name="data" min="2027-01-01" max="2027-12-31" required ${!seasonIsOpen()?'disabled':''}></div><div><label>Distância</label><select name="dist">${['5 km'].map(v=>`<option>${v}</option>`).join('')}</select></div><div><label>Tempo oficial (hh:mm:ss)</label><input name="tempo" required pattern="[0-9]{1,2}:[0-5][0-9]:[0-5][0-9]" placeholder="00:25:30"></div><div><label>Número de peito</label><input name="peito" maxlength="20" required></div><div><label>Colocação geral oficial</label><input type="number" name="colocacao" min="1" max="100000" step="1" required placeholder="Ex.: 12"></div><div><label>Colocação na categoria (opcional)</label><input type="number" name="colocacaoCategoria" min="1" max="100000" step="1" placeholder="Ex.: 3"></div><div class="full"><label>Link público do resultado oficial (ou anexe PDF)</label><input type="url" name="url" pattern="https://.*" placeholder="https://site-da-cronometragem.com/resultado"></div><div class="full"><label>Ou anexar PDF oficial (até 5 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf"></div></div><button class="btn dark" ${!profile||!seasonIsOpen()?'disabled title="Disponível após o pré-cadastro e a abertura da temporada 2027"':''}>Enviar resultado de 2027 para revisão</button></fieldset></form></div></div>${heading('Meus envios','Temporada 2027 • armazenados apenas neste navegador')}<div class="panel">${submissionTable(submissions)}</div><div class="notice">O pré-cadastro é local, sem conta online, autenticação ou sincronização entre dispositivos. Para receber cadastros reais será necessário configurar um banco de dados seguro. Não insira CPF, laudos, dados médicos ou documentos pessoais. O painel Admin é demonstrativo e não oferece controle de acesso.</div>`}
function submissionTable(list,admin=false){return `<div class="tablewrap"><table><thead><tr><th>Prova</th><th>Data</th><th>Tempo</th><th>Colocação</th><th>Comprovação</th><th>Status</th>${admin?'<th>Ação</th>':''}</tr></thead><tbody>${list.map(x=>`<tr><td><strong>${esc(x.prova)}</strong><br>${esc(x.dist)}</td><td>${fmtdate(x.data)}</td><td>${esc(x.tempo)}</td><td>${esc(x.colocacao||'—')}</td><td><a href="${esc(x.url)}" target="_blank" rel="noopener noreferrer">Abrir ↗</a></td><td><span class="status ${x.status}">${x.status}</span></td>${admin?`<td><button onclick="review(${x.id},'aprovado')">Aprovar demo</button> <button onclick="review(${x.id},'rejeitado')">Rejeitar demo</button></td>`:''}</tr>`).join('')||`<tr><td colspan="${admin?7:6}" class="empty">Nenhum resultado enviado.</td></tr>`}</tbody></table></div>`}

async function prepararComprovante(form){const dados=Object.fromEntries(new FormData(form));const file=form.querySelector('input[name="arquivo_pdf"]')?.files?.[0];delete dados.arquivo_pdf;if(!file&&!String(dados.url||'').trim()&&!(betaEditando&&betaMeus.some(r=>Number(r.id)===betaEditando&&r.comprovante_pdf)))throw Error('Informe o link oficial ou selecione um PDF.');if(file){if(file.type!=='application/pdf'||file.size>5*1024*1024||file.size<8)throw Error('Selecione um PDF válido de até 5 MB.');const body=new FormData();body.append('arquivo',file);const response=await fetch('/api/comprovante',{method:'POST',body,credentials:'same-origin'});const result=await response.json();if(!response.ok)throw Error(result.erro||'Falha ao enviar PDF');dados.comprovante_pdf=result.comprovante_pdf}return dados}
function linkComprovante(r){const url=String(r.url||'');const pdf=String(r.comprovante_pdf||'');return `${/^https:\/\//.test(url)?`<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">🔗 Link oficial</a> `:''}${/^[a-f0-9-]{36}$/.test(pdf)?`<a href="/api/comprovante?id=${encodeURIComponent(pdf)}" target="_blank" rel="noopener noreferrer">📄 Abrir PDF</a>`:''}`}
let betaAtletas=[],betaMeus=[],betaFila=[],betaErro='';
async function carregarBeta(){try{betaAtletas=(await onlineRequest('/api/beta2026')).atletas;betaErro='';if(onlineUser){betaMeus=(await onlineRequest('/api/beta2026?meus=1')).resultados;if(onlineUser.roles?.includes('admin'))betaFila=(await onlineRequest('/api/beta2026?fila=1')).resultados}}catch(e){betaErro=e.message}if(['beta2026','admin'].includes(state.page))render()}
async function analisarBeta(id,status){if(!confirm('Confirmar análise de 2026?'))return;try{await onlineRequest('/api/beta2026','PATCH',{id,status});await carregarBeta()}catch(e){alert(e.message)}}
let betaFiltros={tipo:'faixa',sexo:'Todos',faixa:'Todas',dist:'Todas',cidade:'Todos'};
function filtrarBeta(campo,valor){betaFiltros[campo]=valor;if(campo==='tipo'&&valor==='geral')betaFiltros.faixa='Todas';render()}
function filtroBetaSelect(campo,titulo,opcoes){return `<label>${titulo}<select onchange="filtrarBeta('${campo}',this.value)">${opcoes.map(v=>`<option value="${esc(v)}" ${betaFiltros[campo]===v?'selected':''}>${esc(v)}</option>`).join('')}</select></label>`}
function rankingBetaFiltrado(){const porFaixa=betaFiltros.tipo==='faixa',porMunicipio=betaFiltros.tipo==='municipio';const grupos=new Map();for(const a of betaAtletas){const chave=[a.sexo,porFaixa?a.faixa:'GERAL',a.dist,a.classe||'',porMunicipio?a.cidade:'AMAPA'].join('|');if(!grupos.has(chave))grupos.set(chave,[]);grupos.get(chave).push(a)}const linhas=[];for(const [chave,grupo] of grupos){grupo.sort((a,b)=>Number(a.melhor_tempo)-Number(b.melhor_tempo)||String(a.nome).localeCompare(String(b.nome),'pt-BR'));grupo.forEach((a,i)=>{if((betaFiltros.sexo==='Todos'||a.sexo===betaFiltros.sexo)&&(betaFiltros.faixa==='Todas'||!porFaixa||a.faixa===betaFiltros.faixa)&&(betaFiltros.dist==='Todas'||a.dist===betaFiltros.dist)&&(betaFiltros.cidade==='Todos'||a.cidade===betaFiltros.cidade))linhas.push({...a,posicao:i+1,grupo:chave})})}return linhas.sort((a,b)=>(porMunicipio?a.cidade.localeCompare(b.cidade,'pt-BR'):0)||a.dist.localeCompare(b.dist,'pt-BR')||a.sexo.localeCompare(b.sexo,'pt-BR')||(porFaixa?a.faixa.localeCompare(b.faixa,'pt-BR'):0)||a.posicao-b.posicao)}

let betaEditando=null;
function editarBeta(id){const r=betaMeus.find(x=>Number(x.id)===Number(id)&&x.status==='rejeitado');if(!r)return;betaEditando=Number(id);render();const f=document.querySelector('#betaForm');if(!f)return;const campos={prova:r.prova,data:String(r.data).slice(0,10),localidade:r.localidade||'',dist:r.dist,tempo:time(Number(r.tempo_segundos)),colocacao:r.colocacao,url:r.url||''};for(const [nome,valor] of Object.entries(campos)){const campo=f.elements.namedItem(nome);if(campo)campo.value=valor}f.scrollIntoView({behavior:'smooth',block:'start'})}
function cancelarEdicaoBeta(){betaEditando=null;render()}
function beta2026(){return `${heading('🏅 Ranking Experimental 2026','Somente medalha digital e divulgação dos melhores corredores. Sem premiação física ou financeira.')}<div class="panel"><h3>Melhores resultados homologados de 2026</h3><p>Três rankings independentes: geral estadual, por faixa etária e geral por município. Todos consideram categoria e distância. Os resultados não contam para 2027.</p><div class="actions"><button class="btn ${betaFiltros.tipo==='geral'?'':'secondary'}" onclick="filtrarBeta('tipo','geral')">🏆 Ranking geral</button><button class="btn ${betaFiltros.tipo==='faixa'?'':'secondary'}" onclick="filtrarBeta('tipo','faixa')">🏅 Por faixa etária</button><button class="btn ${betaFiltros.tipo==='municipio'?'':'secondary'}" onclick="filtrarBeta('tipo','municipio')">📍 Geral por município</button></div><div class="filters">${filtroBetaSelect('sexo','Categoria',['Todos','Masculino','Feminino','PcD'])}${betaFiltros.tipo==='faixa'?filtroBetaSelect('faixa','Faixa etária',['Todas','Até 17','18–29','30–39','40–49','50–59','60–69','70+']):''}${filtroBetaSelect('dist','Distância',['Todas','5 km'])}${filtroBetaSelect('cidade','Município',['Todos','Amapá','Calçoene','Cutias','Ferreira Gomes','Itaubal','Laranjal do Jari','Macapá','Mazagão','Oiapoque','Pedra Branca do Amapari','Porto Grande','Pracuúba','Santana','Serra do Navio','Tartarugalzinho','Vitória do Jari'])}</div><p class="muted">Ranking geral: posição estadual por categoria e distância. Faixa etária: posição estadual por idade, categoria e distância. Geral por município: posição própria de cada município, sem divisão por idade. Filtrar município não altera as posições estaduais.</p><div class="tablewrap"><table><thead><tr><th>Pos.</th><th>Atleta</th><th>Município</th><th>Categoria</th><th>Faixa etária</th><th>Distância</th><th>Melhor tempo</th></tr></thead><tbody>${rankingBetaFiltrado().map(a=>`<tr><td><span class="place ${a.posicao<=5?'top':''}">${a.posicao}º</span></td><td><strong>${esc(a.nome)}</strong></td><td>${esc(a.cidade)}</td><td>${esc(a.sexo)}${a.classe?' • '+esc(a.classe):''}</td><td>${esc(a.faixa)}</td><td>${esc(a.dist)}</td><td><strong>${time(Number(a.melhor_tempo))}</strong></td></tr>`).join('')||'<tr><td colspan="7">Nenhum resultado homologado encontrado para estes filtros.</td></tr>'}</tbody></table></div>${betaErro?`<p class="notice">${esc(betaErro)}</p>`:''}<button class="btn secondary" onclick="carregarBeta()">Atualizar</button></div><div class="panel"><h3>${betaEditando?'✏️ Corrigir resultado rejeitado':'Cadastrar resultado oficial de 2026'}</h3><p class="muted">Entre na conta e salve seu perfil online antes de enviar. Cada resultado passa por homologação.</p>${!onlineUser||!onlineProfile?'<button class="btn" onclick="go(\'perfil\')">Entrar e concluir cadastro</button>':`<form id="betaForm" class="formgrid"><div class="full"><label>Nome oficial da corrida</label><input name="prova" required minlength="3" maxlength="120"></div><div><label>Data em 2026</label><input name="data" type="date" min="2026-01-01" max="2026-12-31" required></div><div class="full"><label>Localidade onde ocorreu a corrida</label><input name="localidade" maxlength="120" placeholder="Ex.: Macapá/AP — Marco Zero"></div><div><label>Distância</label><select name="dist"><option>5 km</option></select></div><div><label>Tempo oficial (hh:mm:ss)</label><input name="tempo" required pattern="[0-9]{1,2}:[0-5][0-9]:[0-5][0-9]" placeholder="00:25:30"></div><div><label>Colocação geral</label><input type="number" name="colocacao" min="1" required></div><div class="full"><label>Link HTTPS do resultado oficial (opcional se anexar PDF)</label><input type="url" name="url" placeholder="https://..."></div><div class="full"><label>Ou anexar PDF do resultado (até 5 MB)</label><input type="file" name="arquivo_pdf" accept="application/pdf"></div><button class="btn dark">Enviar para homologação</button></form>`}</div><div class="panel"><h3>🏅 Minhas medalhas digitais — 2026</h3><p>As medalhas digitais são liberadas somente após a homologação.</p>${betaMeus.map(r=>`<p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(r.status)} ${r.status==='aprovado'?`<button class="btn secondary" onclick="baixarMedalhaBeta(${Number(r.id)})">Baixar medalha</button>`:r.status==='rejeitado'?`<button class="btn secondary" onclick="editarBeta(${Number(r.id)})">✏️ Editar e reenviar</button>`:''}</p>`).join('')||'<p>Nenhum resultado enviado.</p>'}</div>`}
function baixarMedalhaBeta(id){
 const r=betaMeus.find(x=>Number(x.id)===Number(id)&&x.status==='aprovado');if(!r)return;
 const p=onlineProfile||{},a=betaAtletas.find(x=>Number(x.atleta_id)===Number(r.atleta_id));
 const nome=String(p.nome||a?.nome||'Atleta participante').trim(),prova=String(r.prova||'Corrida oficial').trim();
 const local=String(r.localidade||'Localidade não informada').trim();
 const distancia=String(r.dist||'—'),tempo=time(Number(r.tempo_segundos)),colocacao=Number(r.colocacao)>0?Number(r.colocacao)+'º':'—';
 const escSvg=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&apos;'}[c]));
 const texto=(x,y,v,tam=30,cor='#ffffff',peso=700,alinhamento='middle')=>`<text x="${x}" y="${y}" fill="${cor}" font-family="Arial,Helvetica,sans-serif" font-size="${tam}" font-weight="${peso}" text-anchor="${alinhamento}">${escSvg(v)}</text>`;
 const linhas=(v,max=35,limite=2)=>{const palavras=String(v).split(/\s+/);const out=[];let atual='';for(const palavra of palavras){if((atual+' '+palavra).trim().length>max&&atual){out.push(atual);atual=palavra}else atual=(atual+' '+palavra).trim()}if(atual)out.push(atual);if(out.length>limite){out.length=limite;out[limite-1]=out[limite-1].slice(0,max-1)+'…'}return out};
 const nomeLinhas=linhas(nome,31,2),provaLinhas=linhas(prova,35,2),localLinhas=linhas(local,37,2);
 const foto=String(p.foto_perfil||'');
 const fotoSvg=/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/]+={0,2}$/.test(foto)?`<image href="${foto}" x="170" y="575" width="150" height="150" preserveAspectRatio="xMidYMid slice" clip-path="url(#fotoMedalha)"/>`:`<circle cx="245" cy="650" r="75" fill="#0b5036"/><path d="M245 603a27 27 0 1 1 0 54a27 27 0 0 1 0-54 M192 710c5-57 101-57 106 0" fill="#d7bd64"/>`;
 const svg=`<svg xmlns="http://www.w3.org/2000/svg" width="1200" height="1200" viewBox="0 0 1200 1200" role="img" aria-label="Medalha digital Ranking Amapá Running 2026">
 <defs><radialGradient id="verde"><stop stop-color="#116b49"/><stop offset=".7" stop-color="#07462f"/><stop offset="1" stop-color="#03291e"/></radialGradient><linearGradient id="ouro" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#fff6bc"/><stop offset=".24" stop-color="#c18b20"/><stop offset=".48" stop-color="#ffe486"/><stop offset=".77" stop-color="#a66c12"/><stop offset="1" stop-color="#fbe59a"/></linearGradient><clipPath id="fotoMedalha"><circle cx="245" cy="650" r="75"/></clipPath></defs>
 <rect width="1200" height="1200" fill="#061a13"/><circle cx="600" cy="600" r="578" fill="url(#ouro)"/><circle cx="600" cy="600" r="548" fill="url(#verde)" stroke="#fff0a4" stroke-width="8"/><circle cx="600" cy="600" r="528" fill="none" stroke="#2ef46d" stroke-width="6"/><circle cx="600" cy="600" r="510" fill="none" stroke="#b99539" stroke-width="3"/>
 <path d="M225 389L340 333L405 350L505 280L576 315L673 260L742 305L840 274L970 370" stroke="#24de68" stroke-width="8" fill="none" stroke-linejoin="round" opacity=".85"/>
 <g fill="#e7bf51" stroke="#ffedaa" stroke-width="1" opacity=".95">
 ${Array.from({length:8},(_,i)=>{const y=445+i*64;const x=120+i*9;return `<ellipse cx="${x+25}" cy="${y}" rx="17" ry="39" transform="rotate(-30 ${x+25} ${y})"/><ellipse cx="${1080-i*9-25}" cy="${y}" rx="17" ry="39" transform="rotate(30 ${1080-i*9-25} ${y})"/>`}).join('')}
 </g>
 <g opacity=".85"><path d="M435 540H765M515 540L540 507H660L685 540M560 507L575 485H625L640 507" fill="none" stroke="#d9ba60" stroke-width="5"/><path d="M593 485V457H607V485" fill="#f4d275"/><circle cx="600" cy="454" r="8" fill="#f7e39a"/></g>
 ${texto(600,154,'R A N K I N G',38,'#f4d477')}${texto(600,257,'AMAPÁ',112)}${texto(600,316,'R U N N I N G',48,'#f5d57c')}${texto(600,401,'2026',78,'#ffe58b')}${texto(600,448,'MEDALHA DIGITAL',39)}${texto(600,485,'EDIÇÃO EXPERIMENTAL',25,'#f8d980')}
 <path d="M420 534H780" stroke="#e2b64c" stroke-width="4"/><circle cx="600" cy="534" r="9" fill="#ffe08b"/>
 <rect x="128" y="560" width="944" height="194" rx="49" fill="url(#ouro)" stroke="#fff4c4" stroke-width="5"/>
 <circle cx="245" cy="650" r="87" fill="#e9b848" stroke="#fff6d5" stroke-width="6"/>${fotoSvg}<circle cx="245" cy="650" r="75" fill="none" stroke="#ffeab4" stroke-width="5"/>
 ${nomeLinhas.map((l,i)=>texto(360,632+i*42,l,nomeLinhas.length>1?33:39,'#103b2b',800,'start')).join('')}
 ${texto(360,722,'PARTICIPANTE • RESULTADO HOMOLOGADO',22,'#21523b',700,'start')}
 <rect x="165" y="774" width="870" height="303" rx="35" fill="#063524" stroke="#e8c35f" stroke-width="7"/>
 ${texto(600,816,'PROVA CADASTRADA',22,'#d6b85e')}
 ${provaLinhas.map((l,i)=>texto(600,856+i*34,l,provaLinhas.length>1?29:35,'#ffffff',800)).join('')}
 <path d="M208 924H992" stroke="#9b823d" stroke-width="2"/>
 ${texto(340,955,'DISTÂNCIA',22,'#e8c76e')}${texto(600,955,'TEMPO OFICIAL',22,'#e8c76e')}${texto(857,955,'COLOCAÇÃO',22,'#e8c76e')}
 ${texto(340,1002,distancia,40)}${texto(600,1002,tempo,40)}${texto(857,1002,colocacao,47,'#ffdf78')}
 <path d="M464 940V1020M733 940V1020" stroke="#927c39" stroke-width="2"/>
 ${texto(600,1047,'LOCALIDADE',19,'#e8c76e')}
 ${localLinhas.map((l,i)=>texto(600,1075+i*24,l,localLinhas.length>1?20:23,'#ffffff',600)).join('')}
 ${texto(600,1140,'AMAPÁ • MEIO DO MUNDO • 2026',22,'#f5d982')}
 </svg>`;
 const url=URL.createObjectURL(new Blob([svg],{type:'image/svg+xml;charset=utf-8'}));const link=document.createElement('a');link.href=url;link.download='medalha-amapa-running-2026-'+id+'.svg';link.click();setTimeout(()=>URL.revokeObjectURL(url),1500)
}

function painelBetaAdmin(){if(!onlineUser?.roles?.includes('admin'))return '';return `<section class="panel review-panel"><div class="review-heading"><div><span class="tag">TEMPORADA EXPERIMENTAL</span><h3>🏅 Homologação de resultados — 2026</h3><p class="muted">Confira o resultado publicado pela organização da corrida antes de decidir. Somente resultados aprovados entram no ranking e geram medalhas digitais.</p></div><strong class="review-count">${betaFila.length} pendente(s)</strong></div>${betaFila.map(r=>`<article class="review-item"><div><strong>${esc(r.nome)}</strong><p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(String(r.data).slice(0,10))}</p><p>Tempo: ${time(Number(r.tempo_segundos))} • Colocação geral: ${Number(r.colocacao)}</p>${linkComprovante(r)}</div><div class="review-actions"><button class="btn dark" onclick="analisarBeta(${Number(r.id)},'aprovado')">✓ Homologar</button><button class="btn secondary" onclick="analisarBeta(${Number(r.id)},'rejeitado')">✕ Rejeitar</button></div></article>`).join('')||'<p class="muted">Nenhum resultado experimental aguardando homologação.</p>'}<button class="btn secondary" onclick="carregarBeta()">Atualizar fila de 2026</button></section>`}
function painelResultados2027(){if(!onlineUser?.roles?.includes('admin'))return '';return `<section class="panel review-panel"><div class="review-heading"><div><span class="tag">TEMPORADA OFICIAL</span><h3>🏆 Homologação de resultados — 2027</h3><p class="muted">Verifique a comprovação e os dados antes de homologar. Os resultados aprovados serão considerados na classificação oficial.</p></div><strong class="review-count">${onlineQueue.length} pendente(s)</strong></div>${onlineQueue.map(r=>`<article class="review-item"><div><strong>${esc(r.nome)}</strong><p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(String(r.data).slice(0,10))}</p><p>Tempo: ${time(Number(r.tempo_segundos))} • Colocação geral: ${Number(r.colocacao)}</p><a href="${esc(r.url)}" target="_blank" rel="noopener noreferrer">🔎 Abrir resultado oficial ↗</a></div><div class="review-actions"><button class="btn dark" onclick="onlineApprove(${Number(r.id)},'aprovado')">✓ Homologar</button><button class="btn secondary" onclick="onlineApprove(${Number(r.id)},'rejeitado')">✕ Rejeitar</button></div></article>`).join('')||'<p class="muted">Nenhum resultado oficial aguardando homologação.</p>'}<button class="btn secondary" onclick="onlineRefresh()">Atualizar fila de 2027</button></section>`}

let homologados2026=[],homologados2027=[],homologadosErro='';
async function carregarHomologados(){if(!onlineUser?.roles?.includes('admin'))return;const busca=document.querySelector('#buscaHomologados')?.value||'';try{const q='?homologados=1&busca='+encodeURIComponent(busca);const [a,b]=await Promise.all([onlineRequest('/api/beta2026'+q),onlineRequest('/api/resultados'+q)]);homologados2026=a.resultados||[];homologados2027=b.resultados||[];homologadosErro=''}catch(e){homologadosErro=e.message||'Não foi possível carregar os homologados'}render()}
async function retirarHomologacao(ano,id){if(!onlineUser?.roles?.includes('admin'))return;const lista=ano===2026?homologados2026:homologados2027;const r=lista.find(x=>Number(x.id)===Number(id));if(!r)return;if(!confirm('Retirar a homologação de '+r.nome+' na corrida '+r.prova+' ('+ano+')? O resultado sairá do ranking e deixará de gerar medalha. O cadastro do participante será preservado.'))return;try{await onlineRequest(ano===2026?'/api/beta2026':'/api/resultados','PATCH',{id,status:'revogado'});alert('Homologação retirada. O cadastro do participante foi preservado.');await carregarHomologados();if(ano===2026)await carregarBeta();else await onlineRefresh()}catch(e){alert('Falha ao retirar homologação: '+e.message)}}
function painelHomologados(){if(!onlineUser?.roles?.includes('admin'))return '';const tabela=(ano,lista)=>`<h4>${ano} — ${lista.length} resultado(s) exibido(s)</h4>${lista.map(r=>`<article class="review-item"><div><strong>${esc(r.nome)}</strong><p>${esc(r.prova)} • ${esc(r.dist)} • ${esc(String(r.data).slice(0,10))}</p><p>Tempo: ${time(Number(r.tempo_segundos))} • Colocação: ${Number(r.colocacao)}</p>${linkComprovante(r)}</div><div class="review-actions"><button class="btn secondary" type="button" onclick="retirarHomologacao(${ano},${Number(r.id)})">Retirar homologação</button></div></article>`).join('')||'<p class="muted">Nenhum resultado homologado encontrado.</p>'}`;return `<section class="panel review-panel"><h3>🛡️ Gerenciar resultados homologados</h3><p class="muted">Retire um resultado aprovado do ranking sem excluir a conta ou o perfil do atleta. O resultado passa a rejeitado e deixa de liberar medalha.</p><div class="actions"><input id="buscaHomologados" maxlength="90" placeholder="Buscar por atleta ou corrida"><button type="button" class="btn dark" onclick="carregarHomologados()">Buscar homologados</button></div>${homologadosErro?`<p class="notice">${esc(homologadosErro)}</p>`:''}${tabela(2026,homologados2026)}${tabela(2027,homologados2027)}</section>`}
let adminCadastros=null,adminCadastrosErro='',adminCarregando=false;
async function carregarCadastros(pagina=1){if(!onlineUser?.roles?.includes('admin'))return;adminCarregando=true;adminCadastrosErro='';render();try{const form=document.querySelector('#filtrosCadastros');const f=form?new FormData(form):null;const q=new URLSearchParams({pagina:String(pagina)});if(f)for(const [k,v] of f)if(v)q.set(k,v);adminCadastros=await onlineRequest('/api/admin/atletas?'+q.toString())}catch(e){adminCadastrosErro=e.message||'Falha ao consultar cadastros'}finally{adminCarregando=false;render()}}
async function excluirParticipante(id){if(!onlineUser?.roles?.includes('admin'))return;const atleta=adminCadastros?.atletas?.find(x=>Number(x.id)===Number(id));if(!atleta)return;const ok=confirm('Excluir permanentemente o cadastro de '+atleta.nome+'? Todos os resultados e medalhas associados a esse perfil em 2026 e 2027 serão removidos. Esta ação não pode ser desfeita.');if(!ok)return;const palavra=prompt('Para confirmar a exclusão de '+atleta.nome+', digite EXCLUIR:');if(palavra!=='EXCLUIR'){if(palavra!==null)alert('Exclusão cancelada: confirmação incorreta.');return}try{await onlineRequest('/api/admin/atletas','DELETE',{id,confirmacao:'EXCLUIR'});alert('Cadastro e resultados vinculados excluídos. A conta de acesso não foi apagada.');await carregarCadastros(adminCadastros?.pagina||1);await carregarBeta();await carregarRankingOnline()}catch(e){alert('Não foi possível excluir o participante: '+e.message)}}
function painelCadastros(){if(!onlineUser?.roles?.includes('admin'))return '<div class="notice">Para visualizar pré-cadastros reais, entre com uma conta que tenha a função administrativa. O painel demonstrativo abaixo não consulta o banco online.</div>';const a=adminCadastros;return `<div class="panel"><h3>👥 Pré-cadastros online — temporada 2027</h3><p class="muted">Somente atletas com perfil efetivamente salvo no banco online. Cadastros locais de outros navegadores não aparecem aqui. Para retirar resultados aprovados do ranking, utilize Gerenciar resultados homologados.</p>${a?`<div class="two"><p><strong>${a.total}</strong> atletas online cadastrados</p><p><strong>${a.municipios}</strong> municípios com atletas</p></div>`:''}<form id="filtrosCadastros" class="formgrid"><div><label>Município</label><select name="cidade"><option value="">Todos</option>${['Macapá','Santana','Oiapoque','Porto Grande','Laranjal do Jari','Tartarugalzinho','Pedra Branca do Amapari','Mazagão','Calçoene','Amapá','Ferreira Gomes','Itaubal','Cutias','Pracuúba','Serra do Navio','Vitória do Jari'].map(x=>`<option>${x}</option>`).join('')}</select></div><div><label>Categoria</label><select name="categoria"><option value="">Todas</option><option>Masculino</option><option>Feminino</option><option>PcD</option></select></div><div class="full"><label>Buscar atleta</label><input name="busca" maxlength="90" placeholder="Nome do atleta"></div><button class="btn dark" type="submit">Consultar cadastros</button></form>${adminCarregando?'<p>Consultando banco de dados...</p>':''}${adminCadastrosErro?`<p class="notice">${esc(adminCadastrosErro)}</p>`:''}${a?`<p>${a.totalFiltrado} cadastro(s) encontrados • Página ${a.pagina}</p><div style="overflow-x:auto"><table><thead><tr><th>Atleta</th><th>Município</th><th>Categoria</th><th>Faixa etária</th><th>Situação</th></tr></thead><tbody>${a.atletas.map(x=>`<tr><td>${esc(x.nome)}</td><td>${esc(x.cidade)}</td><td>${esc(x.sexo)}</td><td>${esc(x.faixa)}</td><td>Perfil online salvo</td></tr>`).join('')||'<tr><td colspan="5">Nenhum cadastro encontrado.</td></tr>'}</tbody></table></div><div class="actions">${a.pagina>1?`<button class="btn secondary" type="button" onclick="carregarCadastros(${a.pagina-1})">Anterior</button>`:''}${a.pagina*50<a.totalFiltrado?`<button class="btn secondary" type="button" onclick="carregarCadastros(${a.pagina+1})">Próxima</button>`:''}</div>`:''}</div>`}
function admin(){if(!onlineUser?.roles?.includes('admin'))return `${heading('🔒 Área de homologação','Acesso exclusivo à administração da plataforma')}<div class="panel"><h3>Entre com uma conta administrativa</h3><p>Somente usuários com a função admin podem consultar os resultados pendentes e homologar corridas. O acesso público não permite aprovação ou rejeição.</p><button class="btn" onclick="go('perfil')">Entrar na conta</button></div>`;return `${heading('🛡️ Central de homologação','Conferência de resultados oficiais e gestão por temporada')}<div class="review-summary"><div class="card"><div class="stat">${betaFila.length}</div><strong>Pendentes 2026</strong><p class="muted">Temporada experimental</p></div><div class="card"><div class="stat">${onlineQueue.length}</div><strong>Pendentes 2027</strong><p class="muted">Temporada oficial</p></div></div>${painelBetaAdmin()}${painelResultados2027()}${painelHomologados()}${painelCorridasAdmin()}${painelCadastros()}${painelTreinosAdmin()}`}


// Treino GPS: ranking independente dos resultados oficiais.
let adminTreinos=[],adminTreinosErro="",treinoAtivo=null,treinoHistorico=[],treinoErro='',treinoSalvando=false,treinoModalidade='Masculino';
const treinoDuracao=seg=>{seg=Math.max(0,Math.floor(seg));return String(Math.floor(seg/3600)).padStart(2,'0')+':'+String(Math.floor(seg%3600/60)).padStart(2,'0')+':'+String(seg%60).padStart(2,'0')};
function treinoDistancia(a,b){const rad=Math.PI/180,lat=(b.latitude-a.latitude)*rad,lon=(b.longitude-a.longitude)*rad,x=Math.sin(lat/2)**2+Math.cos(a.latitude*rad)*Math.cos(b.latitude*rad)*Math.sin(lon/2)**2;return 12742000*Math.asin(Math.min(1,Math.sqrt(x)))}
const TREINO_BACKUP='amapa_treino_gps_v1';let treinoBackupTimer=null;
function treinoSalvarBackup(){if(!treinoAtivo)return;const t=treinoAtivo;try{localStorage.setItem(TREINO_BACKUP,JSON.stringify({inicio:t.inicio,metros:t.metros,ultimo:t.ultimo,ultimaPrecisao:t.ultimaPrecisao,descartados:t.descartados,pontosValidos:t.pontosValidos,ultimoSinal:t.ultimoSinal,pausaInicio:t.pausaInicio||null,pausaTotal:t.pausaTotal||0,versao:1}))}catch(e){console.warn('Backup de treino indisponível',e)}}
function treinoLimparBackup(){try{localStorage.removeItem(TREINO_BACKUP)}catch(e){}}
function treinoDuracaoAtiva(t){return Math.max(0,Math.floor((Date.now()-t.inicio-(t.pausaTotal||0)-(t.pausaInicio?Date.now()-t.pausaInicio:0))/1000))}
function treinoReativarGPS(){const t=treinoAtivo;if(!t||!navigator.geolocation)return;if(t.watch!==null&&t.watch!==undefined)navigator.geolocation.clearWatch(t.watch);t.watch=navigator.geolocation.watchPosition(treinoPosicao,treinoFalha,{enableHighAccuracy:true,maximumAge:0,timeout:20000})}
function treinoRecuperar(){if(treinoAtivo||!navigator.geolocation)return;try{const v=JSON.parse(localStorage.getItem(TREINO_BACKUP)||'null');if(!v||v.versao!==1||!Number.isFinite(v.inicio)||Date.now()-v.inicio>86400000)return;if(!Number.isFinite(v.metros)||v.metros<0||v.metros>100000)return;treinoAtivo={...v,watch:null,timer:null,ultimo:null,pausaInicio:null,pausaTotal:(v.pausaTotal||0)+Math.max(0,Date.now()-(v.ultimoSinal||v.inicio)),ultimoSinal:null};treinoErro='Treino recuperado. O intervalo sem GPS foi excluído do tempo ativo; a distância desse intervalo não pode ser recuperada.';treinoReativarGPS();treinoAtivo.timer=setInterval(treinoAtualizarPainel,1000);treinoSalvarBackup();render()}catch(e){console.warn('Não foi possível recuperar treino',e)}}
function treinoVisibilidade(){const t=treinoAtivo;if(!t)return;if(document.hidden){treinoSalvarBackup();return}if(t.ultimoSinal&&Date.now()-t.ultimoSinal>30000){t.ultimo=null;treinoErro='O navegador pode suspender o GPS com a tela bloqueada. Trecho sem sinal não contabilizado.';treinoReativarGPS()}treinoAtualizarPainel()}
if(typeof document!=='undefined'){document.addEventListener('visibilitychange',treinoVisibilidade);window.addEventListener('pagehide',treinoSalvarBackup);window.addEventListener('pageshow',()=>{if(!treinoAtivo)treinoRecuperar()});}
function treinoAtualizarPainel(){const t=treinoAtivo;if(!t)return;const duracao=treinoDuracaoAtiva(t);const ids={gpsDist:(t.metros/1000).toFixed(2).replace('.',',')+' km',gpsTempo:treinoDuracao(duracao),gpsRitmo:t.metros>=10?treinoDuracao(Math.round(duracao/(t.metros/1000)))+' /km':'—',gpsPrecisao:t.ultimaPrecisao?Math.round(t.ultimaPrecisao)+' m':'Aguardando sinal',gpsVelocidade:duracao>0?(t.metros/1000*3600/duracao).toFixed(2).replace('.',',')+' km/h':'—',gpsPontos:duracao>0?((t.metros/1000)*10+(t.metros/1000*3600/duracao)*5).toFixed(2).replace('.',',')+' pts':'0,00 pts'};for(const [id,v] of Object.entries(ids)){const e=document.getElementById(id);if(e)e.textContent=v}}
function treinoPosicao(p){
 const t=treinoAtivo;if(!t||t.pausaInicio)return;
 const c=p.coords,agora=Date.now(),ts=Number(p.timestamp);
 t.ultimaPrecisao=c.accuracy;
 const avisar=msg=>{treinoErro=msg;const el=document.getElementById('treinoAviso');if(el)el.textContent=msg};
 if(!Number.isFinite(ts)||ts>agora+5000||agora-ts>15000||!Number.isFinite(c.accuracy)||c.accuracy>20||c.accuracy<0||!Number.isFinite(c.latitude)||Math.abs(c.latitude)>90||!Number.isFinite(c.longitude)||Math.abs(c.longitude)>180){
  t.descartados++;t.ultimo=null;avisar('Precisão GPS insuficiente ou posição desatualizada. Aguardando sinal confiável; trecho não contabilizado.');treinoAtualizarPainel();return;
 }
 const atual={latitude:c.latitude,longitude:c.longitude,timestamp:ts,accuracy:c.accuracy};
 if(!t.ultimo){t.ultimo=atual;t.ultimoSinal=agora;t.pontosValidos++;treinoErro='GPS confiável. Monitorando percurso.';treinoSalvarBackup();treinoAtualizarPainel();return}
 const seg=(ts-t.ultimo.timestamp)/1000;
 if(seg<=0){treinoAtualizarPainel();return}
 if(seg>15){t.ultimo=atual;t.descartados++;t.ultimoSinal=agora;avisar('Sinal GPS interrompido. Trecho sem sinal ignorado para evitar distância duplicada.');treinoSalvarBackup();treinoAtualizarPainel();return}
 const metros=treinoDistancia(t.ultimo,atual);
 const margem=Math.max(3,Math.min(10,(atual.accuracy+t.ultimo.accuracy)*.3));
 if(metros<=margem){t.ultimoSinal=agora;treinoAtualizarPainel();return}
 const velocidade=metros/seg;
 if(velocidade>7.5){t.descartados++;t.ultimo=null;avisar('Salto de GPS descartado. Aguardando novo ponto para retomar a medição.');treinoAtualizarPainel();return}
 t.metros+=metros;t.ultimo=atual;t.pontosValidos++;t.ultimoSinal=agora;treinoErro='GPS confiável. Distância calculada pelos pontos válidos.';treinoSalvarBackup();treinoAtualizarPainel();
}
function treinoPausar(){const t=treinoAtivo;if(!t||t.pausaInicio)return;t.pausaInicio=Date.now();t.ultimo=null;treinoErro='Treino pausado: distância não contabilizada.';treinoSalvarBackup();render()}
function treinoRetomar(){const t=treinoAtivo;if(!t||!t.pausaInicio)return;t.pausaTotal=(t.pausaTotal||0)+Date.now()-t.pausaInicio;t.pausaInicio=null;t.ultimo=null;treinoErro='Treino retomado. Aguardando novo ponto GPS.';treinoSalvarBackup();render()}
function treinoFalha(e){treinoErro='GPS indisponível: '+(e?.message||'verifique a permissão de localização');if(treinoAtivo)treinoAtivo.ultimo=null;const x=document.getElementById('treinoAviso');if(x)x.textContent=treinoErro}
function treinoIniciar(){if(treinoAtivo)return;if(!navigator.geolocation||!window.isSecureContext){alert('O GPS exige HTTPS e um navegador com permissão de localização.');return}treinoErro='';treinoAtivo={inicio:Date.now(),metros:0,ultimo:null,ultimaPrecisao:null,watch:null,timer:null,descartados:0,pontosValidos:0,ultimoSinal:null};treinoAtivo.watch=navigator.geolocation.watchPosition(treinoPosicao,treinoFalha,{enableHighAccuracy:true,maximumAge:0,timeout:20000});treinoAtivo.timer=setInterval(treinoAtualizarPainel,1000);render()}
async function treinoParar(){if(!treinoAtivo)return;const t=treinoAtivo;treinoAtivo=null;navigator.geolocation.clearWatch(t.watch);clearInterval(t.timer);treinoSalvarBackup();const duracao=treinoDuracaoAtiva(t),metros=Math.round(t.metros);if(metros<10||duracao<30||t.pontosValidos<3||!t.ultimoSinal||Date.now()-t.ultimoSinal>90000){alert('Treino encerrado. Para entrar no ranking, registre ao menos 10 metros, 30 segundos e pelo menos 3 pontos de GPS válidos, com sinal recente.');render();return}if(!onlineUser||!onlineProfile){alert('Treino concluído e mantido no dispositivo para recuperação: '+(metros/1000).toFixed(2)+' km em '+treinoDuracao(duracao)+'. Entre na conta e complete o perfil antes de iniciar outro treino para salvar no ranking.');render();return}treinoSalvando=true;render();try{await onlineRequest('/api/treinos','POST',{distancia_m:metros,duracao_s:duracao,iniciado_em:new Date(t.inicio).toISOString()});await treinoCarregar();treinoLimparBackup();alert('Treino registrado no ranking de treinos!')}catch(e){alert('Treino encerrado, mas não foi salvo no ranking: '+e.message)}finally{treinoSalvando=false;render()}}
async function treinoCarregar(){try{const r=await fetch('/api/treinos',{cache:'no-store'});if(!r.ok)throw Error('Ranking indisponível');const j=await r.json();treinoHistorico=j.treinos||[];treinoErro=''}catch(e){treinoErro=e.message}if(state.page==='treino')render()}

// Importação local: comprovantes não são pontuados automaticamente.
function treinoImportacaoStatus(msg){const el=document.getElementById('treinoImportacaoStatus');if(el)el.textContent=msg}
async function treinoLerImagem(file){
 if(!window.Tesseract){
  await new Promise((resolve,reject)=>{const s=document.createElement('script');s.src='https://cdn.jsdelivr.net/npm/tesseract.js@5.1.1/dist/tesseract.min.js';s.onload=resolve;s.onerror=()=>reject(Error('Leitor de imagens indisponível. Verifique a conexão.'));document.head.appendChild(s)})
 }
 const resultado=await window.Tesseract.recognize(file,'por+eng');
 const texto=resultado.data.text||'';
 const distancia=texto.match(/(?:dist[aâ]ncia|distance|dist)\s*[:\-]?\s*(\d{1,3}(?:[.,]\d{1,2})?)\s*(km|quil[oô]metros?)/i)||texto.match(/(\d{1,3}(?:[.,]\d{1,2})?)\s*(km)\b/i);
 const tempo=texto.match(/(?:tempo|dura[cç][aã]o|moving time|elapsed time|time)\s*[:\-]?\s*(\d{1,2}:\d{2}(?::\d{2})?)/i);
 const d=distancia?Number(distancia[1].replace(',','.')):null;
 const segundos=tempo?tempo[1].split(':').map(Number).reduce((a,b)=>a*60+b,0):null;
 return {texto:texto.slice(0,3500),distancia:Number.isFinite(d)?d:null,tempo:segundos};
}
async function treinoImportarArquivo(input){
 const file=input.files&&input.files[0];if(!file)return;
 if(file.size>10*1024*1024){treinoImportacaoStatus('Arquivo excede 10 MB. Selecione um arquivo menor.');input.value='';return}
 const ext=(file.name.split('.').pop()||'').toLowerCase();
 if(!['gpx','tcx','csv','fit','jpg','jpeg','png','webp','pdf'].includes(ext)){treinoImportacaoStatus('Formato não permitido.');input.value='';return}
 try{
  if(ext==='gpx'||ext==='tcx'){
   if(!onlineUser||!onlineProfile)throw Error('Entre na conta e complete seu perfil para classificar automaticamente.');
   treinoImportacaoStatus('Conferindo percurso e dados no servidor...');
   const r=await onlineRequest('/api/treinos','POST',{importacao:true,tipo:ext,conteudo:await file.text()});
   treinoImportacaoStatus('Treino aprovado na conferência automática: '+(r.distancia_m/1000).toFixed(2).replace('.',',')+' km em '+treinoDuracao(r.duracao_s)+'. Classificado no ranking de treinos.');
   await treinoCarregar();return;
  }
  let resumo='';let distancia=null;let tempo=null;
  if(ext==='gpx'||ext==='tcx'){
   const xml=new DOMParser().parseFromString(await file.text(),'application/xml');
   if(xml.querySelector('parsererror'))throw Error('XML inválido');
   const tag=ext==='gpx'?'trkpt':'Trackpoint';
   const pts=Array.from(xml.getElementsByTagName(tag)).map(p=>{
    const lat=ext==='gpx'?Number(p.getAttribute('lat')):Number(p.getElementsByTagName('LatitudeDegrees')[0]?.textContent);
    const lon=ext==='gpx'?Number(p.getAttribute('lon')):Number(p.getElementsByTagName('LongitudeDegrees')[0]?.textContent);
    const ts=Date.parse(p.getElementsByTagName(ext==='gpx'?'time':'Time')[0]?.textContent||'');
    return {latitude:lat,longitude:lon,timestamp:ts};
   }).filter(p=>Number.isFinite(p.latitude)&&Math.abs(p.latitude)<=90&&Number.isFinite(p.longitude)&&Math.abs(p.longitude)<=180&&Number.isFinite(p.timestamp));
   if(pts.length<2)throw Error('Arquivo sem pontos de percurso suficientes');
   let metros=0;let validos=0;
   for(let i=1;i<pts.length;i++){const dt=(pts[i].timestamp-pts[i-1].timestamp)/1000;if(dt<=0||dt>30)continue;const d=treinoDistancia(pts[i-1],pts[i]);if(d>0&&d/dt<=7.5){metros+=d;validos++}}
   if(!validos)throw Error('Percurso sem trechos válidos');
   distancia=(metros/1000).toFixed(2);tempo=Math.round((pts[pts.length-1].timestamp-pts[0].timestamp)/1000);
   resumo='Percurso lido: '+distancia+' km; duração total '+treinoDuracao(tempo)+'. Dados sujeitos à conferência.';
  }else if(ext==='csv'){
   const txt=await file.text();const linhas=txt.trim().split(/\r?\n/);
   if(linhas.length<2)throw Error('CSV vazio ou incompleto');
   resumo='CSV recebido ('+(linhas.length-1)+' linhas). A estrutura precisa ser conferida antes de calcular distância.';
  }else if(ext==='fit'){resumo='Arquivo FIT recebido. A leitura automática deste formato ainda não está disponível.'}
  else if(['jpg','jpeg','png','webp'].includes(ext)){
   treinoImportacaoStatus('Lendo texto da imagem. Aguarde...');
   const leitura=await treinoLerImagem(file);
   distancia=leitura.distancia;tempo=leitura.tempo;
   resumo='Leitura automática da imagem: '+(distancia!==null?distancia.toFixed(2)+' km':'distância não identificada')+'; '+(tempo!==null?treinoDuracao(tempo):'tempo não identificado')+'. '+(leitura.texto?'Texto reconhecido: '+leitura.texto.slice(0,350).replace(/\\s+/g,' '):'Nenhum texto reconhecido.')+' Confira os dados; imagem não comprova autenticidade.';
  }else resumo='PDF recebido. Leitura automática de PDF ainda não disponível; exige conferência.';
  const chave='amapa_importacoes_pendentes_v1';
  const itens=JSON.parse(localStorage.getItem(chave)||'[]');
  itens.unshift({nome:file.name,tipo:ext,tamanho:file.size,data:new Date().toISOString(),distancia,tempo,status:'Pendente de validação'});
  localStorage.setItem(chave,JSON.stringify(itens.slice(0,30)));
  treinoImportacaoStatus(resumo+' Registro pendente salvo neste navegador, sem envio ao servidor e sem pontos no ranking.');
 }catch(e){treinoImportacaoStatus('Não foi possível importar: '+e.message)}
 input.value='';
}
function treino(){const t=treinoAtivo;const classificados=treinoHistorico.filter(x=>x.sexo===treinoModalidade);return `${heading('🏃 Registro de treinos','Envie atividades e comprovantes para conferência')}<div class="panel treino-panel"><div class="treino-section-head"><div><span class="treino-eyebrow">IMPORTAÇÃO DE ATIVIDADES</span><h3>📁 Importar treino ou comprovante</h3></div></div><p>Envie GPX, TCX, FIT, CSV, JPG, PNG, WEBP ou PDF (até 10 MB). GPX e TCX válidos são classificados automaticamente após conferência do percurso. Imagens JPG, PNG e WEBP têm leitura automática de distância e tempo quando legíveis, mas não geram pontos sem validação. FIT, CSV e PDF exigem validação adicional.</p><label class="btn secondary" for="treinoArquivo">Selecionar arquivo</label><input id="treinoArquivo" type="file" accept=".gpx,.tcx,.fit,.csv,.jpg,.jpeg,.png,.webp,.pdf" onchange="treinoImportarArquivo(this)" style="display:block;margin-top:12px;max-width:100%"><p class="muted" id="treinoImportacaoStatus" role="status">GPX e TCX passam por conferência automática no servidor e, quando válidos, entram no ranking. FIT, CSV, imagens e PDFs ficam pendentes neste dispositivo, sem pontuação automática.</p></div><div class="panel treino-panel"><div class="treino-section-head"><div><span class="treino-eyebrow">CLASSIFICAÇÃO ACUMULADA</span><h3>🏅 Ranking de treinos</h3></div><span class="treino-live">Atualização online</span></div><div class="actions treino-ranking-tabs"><button class="btn ${treinoModalidade==='Masculino'?'':'secondary'}" type="button" onclick="treinoSelecionarModalidade('Masculino')">♂ Masculino</button><button class="btn ${treinoModalidade==='Feminino'?'':'secondary'}" type="button" onclick="treinoSelecionarModalidade('Feminino')">♀ Feminino</button></div><p class="muted">Pontuação acumulada: 10 pontos por km + 5 pontos por km/h de velocidade média em cada treino. A soma de todos os treinos válidos define a classificação. Empate: maior distância total, depois menor tempo total. Sem premiação física.</p><div class="tablewrap treino-tablewrap"><table><thead><tr><th>Pos.</th><th>Atleta</th><th>Município</th><th>Treinos</th><th>Distância total</th><th>Tempo total</th><th>Pontos acumulados</th></tr></thead><tbody>${classificados.map((x,i)=>`<tr><td>${i+1}º</td><td>${esc(x.nome)}</td><td>${esc(x.cidade)}</td><td>${Number(x.quantidade_treinos)}</td><td>${(Number(x.distancia_total_m)/1000).toFixed(2).replace('.',',')} km</td><td>${treinoDuracao(x.duracao_total_s)}</td><td><strong>${Number(x.pontos_totais).toFixed(2).replace('.',',')}</strong></td></tr>`).join('')||'<tr><td colspan="7">Ainda não há treinos registrados.</td></tr>'}</tbody></table></div></div>`}
async function carregarAdminTreinos(){if(!onlineUser?.roles?.includes('admin'))return;try{const r=await onlineRequest('/api/admin/treinos');adminTreinos=r.treinos||[];adminTreinosErro=''}catch(e){adminTreinosErro=e.message}if(state.page==='admin')render()}
async function removerTreinoAdmin(id){if(!onlineUser?.roles?.includes('admin'))return;const t=adminTreinos.find(x=>Number(x.id)===Number(id));if(!t||t.removido_em)return;const motivo=prompt('Motivo da remoção do treino de '+t.nome+' (obrigatório):');if(motivo===null)return;if(motivo.trim().length<5){alert('Informe um motivo com pelo menos 5 caracteres.');return}if(!confirm('Confirmar remoção do treino #'+id+'? A pontuação deste treino será retirada do ranking.'))return;try{await onlineRequest('/api/admin/treinos','DELETE',{id,motivo:motivo.trim()});await carregarAdminTreinos();await treinoCarregar();alert('Treino removido do ranking e pontuação recalculada.')}catch(e){alert(e.message)}}
function painelTreinosAdmin(){if(!onlineUser?.roles?.includes('admin'))return '';return `<div class="panel"><h3>🏃 Gerenciar treinos e pontuação</h3><p class="muted">Remova treinos individuais com justificativa. A exclusão é lógica e auditável: o treino deixa de contar na pontuação acumulada e no ranking, mas permanece registrado para conferência.</p><div class="actions"><button class="btn secondary" onclick="carregarAdminTreinos()">Atualizar lista</button></div>${adminTreinosErro?'<p class="notice">'+esc(adminTreinosErro)+'</p>':''}<div class="tablewrap"><table><thead><tr><th>ID</th><th>Atleta</th><th>Data</th><th>Distância</th><th>Tempo</th><th>Pontos</th><th>Situação / ação</th></tr></thead><tbody>${adminTreinos.map(x=>`<tr><td>#${Number(x.id)}</td><td>${esc(x.nome)}<br><small>${esc(x.cidade)} • ${esc(x.sexo)}</small></td><td>${esc(new Date(x.iniciado_em).toLocaleString('pt-BR'))}</td><td>${(Number(x.distancia_m)/1000).toFixed(2).replace('.',',')} km</td><td>${treinoDuracao(x.duracao_s)}</td><td>${Number(x.pontos).toFixed(2).replace('.',',')}</td><td>${x.removido_em?'<span class="muted">Removido • '+esc(x.motivo_remocao||'')+'</span>':'<button class="btn secondary" onclick="removerTreinoAdmin('+Number(x.id)+')">Remover treino</button>'}</td></tr>`).join('')||'<tr><td colspan="7">Nenhum treino carregado. Clique em Atualizar lista.</td></tr>'}</tbody></table></div></div>`}
function treinoSelecionarModalidade(modalidade){if(!['Masculino','Feminino'].includes(modalidade))return;treinoModalidade=modalidade;render()}
function go(p){if(p==='desafios')p='inicio';state.page=p;if(p==='beta2026'||p==='admin')carregarBeta();if(['rankings','premiacao'].includes(p)&&!rankingOnline&&!rankingOnlineErro)carregarRankingOnline();if(p==='provas')carregarCorridas();if(p==='treino'){treinoRecuperar();treinoCarregar()}if(p==='perfil'&&onlineUser)carregarPerfilTreinos();if(p==='admin'&&onlineUser?.roles?.includes('admin')){carregarAdminCorridas();carregarHomologados();carregarAdminTreinos()}if(p==='admin'&&onlineUser?.roles?.includes('admin')&&!adminCadastros&&!adminCarregando)carregarCadastros();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===p));render();window.scrollTo({top:0,behavior:'smooth'})}function setType(t){state.tipo=t;render()}function review(id,status){submissions=submissions.map(x=>x.id===id?{...x,status}:x);persist();render()}function render(){let pages={inicio,rankings,provas,premiacao,perfil,admin,beta2026,treino};$('#app').innerHTML=pages[state.page]();if(state.page==='rankings')for(const id of ['sexo','faixa','dist','cidade','classe'])$('#'+id).addEventListener('change',e=>{state[id]=e.target.value;render()});if(state.page==='beta2026'){const f=$('#betaForm');if(f)f.addEventListener('submit',async e=>{e.preventDefault();try{const dados=await prepararComprovante(f);if(betaEditando){dados.editar_id=betaEditando;const anterior=betaMeus.find(r=>Number(r.id)===betaEditando);if(anterior?.comprovante_pdf&&!dados.comprovante_pdf)dados.comprovante_pdf=anterior.comprovante_pdf}await onlineRequest('/api/beta2026','POST',dados);alert(betaEditando?'Resultado corrigido e reenviado para homologação.':'Resultado de 2026 enviado para homologação.');betaEditando=null;await carregarBeta()}catch(err){alert(err.message)}})}if(state.page==='provas'){const f=$('#corridaForm');if(f)f.addEventListener('submit',async e=>{e.preventDefault();try{const dados=Object.fromEntries(new FormData(f));await onlineRequest('/api/corridas','POST',dados);alert('Corrida enviada para homologação administrativa.');f.reset()}catch(err){alert('Não foi possível cadastrar: '+err.message)}})}if(state.page==='admin'){const f=$('#filtrosCadastros');if(f)f.addEventListener('submit',e=>{e.preventDefault();carregarCadastros(1)})}if(state.page==='perfil'){const loginForm=$('#onlineLogin');if(loginForm)loginForm.addEventListener('submit',async e=>{e.preventDefault();const b=new FormData(e.target);const action=e.submitter?.value||'login';try{const auth=window.onlineAuth;if(!auth||typeof auth[action]!=='function')throw Error('O módulo de autenticação não carregou. Atualize a página; se persistir, é necessário corrigir a compilação do site no Netlify.');await auth[action](b.get('email'),b.get('password'));await onlineRefresh();alert(action==='signup'?'Conta solicitada. Confirme seu e-mail antes de entrar.':'Login realizado.')}catch(err){alert(err?.message||'Não foi possível acessar a autenticação.')}}); $('#profileForm').addEventListener('submit',async e=>{e.preventDefault();profile=Object.fromEntries(new FormData(e.target));persist();if(onlineUser){try{onlineProfile=(await onlineRequest('/api/atleta','POST',profile)).atleta;alert('Pré-cadastro de 2027 salvo no banco online e neste navegador.')}catch(err){alert('Pré-cadastro salvo apenas neste navegador. Não foi possível sincronizar online: '+(err?.message||'erro desconhecido'))}}else{alert('Dados guardados neste navegador. Após criar e confirmar sua conta e entrar, a plataforma tentará enviar automaticamente o pré-cadastro ao banco online.')}render()});$('#resultForm').addEventListener('submit',async e=>{e.preventDefault();if(!onlineUser||!onlineProfile){alert('Entre na sua conta e conclua o perfil online.');return}if(!seasonIsOpen()){alert('Os resultados de 2027 poderão ser enviados a partir de 1º de janeiro de 2027.');return}try{const v=await prepararComprovante(e.target);if(!/^2027-\d{2}-\d{2}$/.test(v.data))throw Error('Apenas resultados de 2027 são aceitos.');if(new Date(v.data+'T12:00:00')>new Date())throw Error('Não é possível cadastrar resultados futuros.');await onlineRequest('/api/resultados','POST',v);alert('Resultado oficial de 2027 enviado para homologação.');await onlineRefresh()}catch(err){alert(err.message)} })}}document.querySelectorAll('nav button').forEach(b=>b.addEventListener('click',()=>go(b.dataset.page)));render();
